import React from 'react';
import CaseVisual, { isArsenalCase } from './CaseVisual';
import ImageWithFallback from './ImageWithFallback';
import { resolveCaseImage } from '../utils/caseAssets';
import './CaseOpeningSplashUnified.css';

// IMPORTANT: use the bundled local artwork for Arsenal splashes.
// Do not rely on API image_url values or dynamically built paths: the API
// intentionally points Arsenal cards to category thumbnails, while the splash
// needs its dedicated artwork. Local imports are processed by webpack and
// therefore cannot become a production 404 because of a bad relative URL.
import pistolArsenalArt from '../assets/items/deagle_blaze.png';
import rifleArsenalArt from '../assets/items/ak_vulcan.png';
import sniperArsenalArt from '../assets/items/awp_dragon_lore.png';
import knifeArsenalArt from '../assets/items/karambit_fade.png';
import glovesArsenalArt from '../assets/items/sport_vice.png';

const normalize = (value = '') => String(value)
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]/g, '');

const ARSENAL_ART = {
  pistol: { art: pistolArsenalArt, label: 'PISTOL ARSENAL', accent: '#d6ae5a' },
  rifle: { art: rifleArsenalArt, label: 'RIFLE ARSENAL', accent: '#cf6a7f' },
  sniper: { art: sniperArsenalArt, label: 'SNIPER ARSENAL', accent: '#76b7df' },
  knife: { art: knifeArsenalArt, label: 'KNIFE ARSENAL', accent: '#d7bb6f' },
  gloves: { art: glovesArsenalArt, label: 'GLOVES ARSENAL', accent: '#75abc2' },
};

const getArsenalKind = (caseData = {}) => {
  const n = normalize(`${caseData?.name || ''} ${caseData?.type || ''} ${caseData?.category || ''}`);
  if (n.includes('pistolarsenal')) return 'pistol';
  if (n.includes('riflearsenal') || n.includes('assaultriflearsenal')) return 'rifle';
  if (n.includes('sniperarsenal') || n.includes('awparsenal')) return 'sniper';
  if (n.includes('knifearsenal') || n.includes('knivesarsenal')) return 'knife';
  if (n.includes('glovesarsenal') || n.includes('glovearsenal')) return 'gloves';
  return null;
};

function ArsenalSplash({ caseData, kind }) {
  const meta = ARSENAL_ART[kind];
  const [failed, setFailed] = React.useState(false);

  if (!meta || failed) {
    return <CaseVisual caseData={caseData} large splash />;
  }

  return (
    <div className="wc66-arsenal-splash" data-arsenal-kind={kind}>
      <div className="wc66-arsenal-grid" />
      <div className="wc66-arsenal-beam" style={{ '--arsenal-accent': meta.accent }} />
      <div className="wc66-arsenal-copy">
        <span>ARSENAL / DROP POOL</span>
        <strong>{meta.label}</strong>
        <small>{caseData?.description || 'Pool spécialisé WellCase'}</small>
      </div>
      <div className="wc66-arsenal-art-wrap">
        <img
          src={meta.art}
          alt={meta.label}
          className="wc66-arsenal-art"
          draggable="false"
          onError={() => setFailed(true)}
        />
      </div>
      <div className="wc66-arsenal-chip">POOL {kind.toUpperCase()} · DROP SÉCURISÉ</div>
    </div>
  );
}

export default function CaseOpeningSplashUnified({ caseData }) {
  const arsenalKind = getArsenalKind(caseData);
  const accent = arsenalKind ? ARSENAL_ART[arsenalKind].accent : '#58697a';
  const arsenal = Boolean(arsenalKind) || isArsenalCase(caseData?.name);

  return (
    <div
      className="wc61-splash"
      style={{ '--wc61-accent': accent }}
      data-splash-version="66-fixed"
      data-arsenal={arsenal ? 'true' : 'false'}
      role="dialog"
      aria-label={`Ouverture de ${caseData?.name || 'caisse'}`}
    >
      <div className="wc61-backdrop" />
      <div className="wc61-card">
        <div className="wc61-kicker">WELLCASE / OUVERTURE SÉCURISÉE</div>
        <h1>{caseData?.name || 'WELLCASE'}</h1>
        <div className="wc61-stage">
          {arsenalKind ? (
            <ArsenalSplash caseData={caseData} kind={arsenalKind} />
          ) : arsenal ? (
            <CaseVisual caseData={caseData} large splash />
          ) : (
            <div className="wc61-case-art">
              <ImageWithFallback
                src={resolveCaseImage(caseData)}
                alt={caseData?.name || 'WELLCASE'}
                className="wc61-case-art-image"
              />
            </div>
          )}
        </div>
        <div className="wc61-status"><span />DROP SÉCURISÉ</div>
        <div className="wc61-progress"><i /></div>
      </div>
    </div>
  );
}
